<Project>
  <PropertyGroup>
    <ManagePackageVersionsCentrally>true</ManagePackageVersionsCentrally>
    <CentralPackageFloatingVersionsEnabled>true</CentralPackageFloatingVersionsEnabled>
    <!--
      Default must match UmbracoAppLocalIcuVersion in Umbraco.Bench.Umbraco.csproj. Defined here too because this file
      is imported before the main project's own PropertyGroup runs, so under CPM the PackageVersion below needs
      its own fallback to stay in sync with the RuntimeHostConfigurationOption value set from the same property.
    -->
    <UmbracoAppLocalIcuVersion Condition="'$(UmbracoAppLocalIcuVersion)' == ''">72.1.0.3</UmbracoAppLocalIcuVersion>
  </PropertyGroup>
  <ItemGroup>
    <PackageVersion Include="Umbraco.Cms" Version="18.2.0" />
    <PackageVersion Include="Umbraco.Cms.DevelopmentMode.Backoffice" Version="18.2.0" />
    <PackageVersion Include="Microsoft.ICU.ICU4C.Runtime" Version="$(UmbracoAppLocalIcuVersion)" />
    <PackageVersion Include="uSync" Version="18.1.4" />
  </ItemGroup>
</Project>=====

WebApplicationBuilder builder = WebApplication.CreateBuilder(args);

#if DEBUG
builder.Configuration.AddJsonFile("appsettings.Local.json", optional: true, reloadOnChange: true);
#endif

builder.CreateUmbracoBuilder()
    .AddBackOffice()
    .AddWebsite()
    .AddComposers()
    .Build();

WebApplication app = builder.Build();


await app.BootUmbracoAsync();


app.UseUmbraco()
    .WithMiddleware(u =>
    {
        u.UseBackOffice();
        u.UseWebsite();
    })
    .WithEndpoints(u =>
    {
        u.UseBackOfficeEndpoints();
        u.UseWebsiteEndpoints();
    });

await app.RunAsync();
using Microsoft.Extensions.DependencyInjection;
using Umbraco.Bench.Umbraco.Migrations;
using Umbraco.Bench.Umbraco.Notifications;
using Umbraco.Bench.Umbraco.Services;
using Umbraco.Cms.Core.Composing;
using Umbraco.Cms.Core.Notifications;

namespace Umbraco.Bench.Umbraco.Composers;

public class ProjectComposer : IComposer
{
    public void Compose(IUmbracoBuilder builder)
    {
        // Transient: migrations are resolved from the root provider, where scoped services fail
        builder.Services.AddTransient<DataTypeOrganizationService>();

        builder.AddNotificationAsyncHandler<DataTypeSavedNotification, DataTypeSavedHandler>();
        builder.AddNotificationAsyncHandler<UmbracoApplicationStartedNotification, McpApiUserHandler>();

        builder.PackageMigrationPlans()
            .Add<ProjectMigrationPlan>();
    }
}

