    "Umbraco.BlockGrid": [
      {
        "contentKey": "<uuid>",           // required
        "settingsKey": "<uuid|null>",
        "columnSpan": <int >= 1>,
        "rowSpan": <int >= 1>,
        "areas": [ { "key": "<uuid>", "items": [ <layoutItem> ] } ]
      }
    ]
  },
  "contentData": [
    {
      "key": "<uuid>",                    // required
      "contentTypeKey": "<uuid>",         // required, enum = my 4 block types
      "values": [                          // <-- "values", array of { alias, culture, segment, value }
        { "alias": "<propAlias>", "culture": null, "segment": null, "value": <any> }
      ]
