import fs from "node:fs";

const file = "C:/Users/kaspa/.claude/projects/C--code-benchmark-Umbraco-Bench/6ca1d433-7084-426c-af56-39d320b3044e.jsonl";
const SUBSTRINGS = ["create-document", "create-and-publish", "update-document", "update-and-publish", "publish-document", "copy-document", "move-document", "delete-document", "unpublish-document"];

const calls = [];
const results = new Map();

function walk(o, line) {
  if (Array.isArray(o)) { for (const v of o) walk(v, line); return; }
  if (!o || typeof o !== "object") return;
  if (o.type === "tool_use" && typeof o.name === "string"
      && SUBSTRINGS.some(s => o.name.includes(s))
      && !o.name.includes("-type") && !o.name.includes("folder")) {
    calls.push({ id: o.id, line, name: o.name, input: o.input ?? {} });
  }
  if (o.type === "tool_result" && o.tool_use_id) {
    let text = "";
    if (Array.isArray(o.content)) text = o.content.map(c => (typeof c === "string" ? c : (c.text ?? ""))).join("\n");
    else if (typeof o.content === "string") text = o.content;
    results.set(o.tool_use_id, text);
  }
  for (const v of Object.values(o)) walk(v, line);
}

const raw = fs.readFileSync(file, "utf8");
const lines = raw.split("\n");
lines.forEach((line, i) => {
  const t = line.trim();
  if (!t) return;
  let o;
  try { o = JSON.parse(t); } catch { return; }
  walk(o, i + 1);
});

calls.sort((a, b) => a.line - b.line);

const trunc = (v, n) => (typeof v === "string" && v.length > n ? v.slice(0, n) + "…[len " + v.length + "]" : v);

for (const c of calls) {
  console.log("\n===== line " + c.line + " — " + c.name + " =====");
  const out = {};
  for (const [k, v] of Object.entries(c.input)) {
    if (k === "values" || k === "properties" || k === "data") out[k] = v;
    else out[k] = trunc(v, 150);
  }
  console.log(JSON.stringify(out, null, 1));
  const res = results.get(c.id);
  console.log("--- result ---\n" + (res === undefined ? "(not found)" : trunc(res, 3000)));
}
console.log("\nTotal content-write calls: " + calls.length);

